SELECT name, price
FROM products
WHERE price > 500;

-- This returns nothing, even though Hari has no city:
SELECT name FROM customers WHERE city = NULL;

-- This is the correct way:
SELECT name, city FROM customers WHERE city IS NULL;

SELECT name, city, joined
FROM customers
WHERE city = 'Nairobi' AND joined >= '2024-05-01';

SELECT name, category, price
FROM products
WHERE category = 'Bags' OR price < 100;

-- names that start with A
SELECT name FROM customers WHERE name LIKE 'A%';

-- names that end with 'Rao'
SELECT name FROM customers WHERE name LIKE '%Rao';

-- names with a letter 'k' anywhere
SELECT name FROM customers WHERE name LIKE '%k%';

-- a three-letter product code starting with P, like P01
SELECT name FROM products WHERE name LIKE 'P__';

SELECT name, price
FROM products
ORDER BY price;

SELECT name, price
FROM products
ORDER BY price DESC;

SELECT category, name, price
FROM products
ORDER BY category ASC, price DESC;

SELECT UPPER(name) AS shout, LENGTH(name) AS letters
FROM customers
WHERE id <= 3;

SELECT name, COALESCE(city, 'Unknown') AS city
FROM customers
WHERE id >= 7;

SELECT COUNT(*) AS delivered_orders
FROM orders
WHERE status = 'delivered';

SELECT name
FROM customers
WHERE id IN (SELECT customer_id FROM orders WHERE status = 'shipped');

-- This returns Hari Singh, because customer_id is never NULL in orders:
SELECT name FROM customers WHERE id NOT IN (SELECT customer_id FROM orders);

-- But this returns nothing at all:
SELECT name FROM customers WHERE id NOT IN (1, 2, NULL);

SELECT c.name
FROM customers AS c
WHERE NOT EXISTS (
  SELECT 1 FROM orders AS o WHERE o.customer_id = c.id
);

UPDATE customers
SET city = 'Pune'
WHERE id = 8;

UPDATE products
SET price = price + 10
WHERE category = 'Stationery';

-- Step 1: look at what would change
SELECT * FROM products WHERE category = 'Stationery';

-- Step 2: change it
UPDATE products SET price = price + 10 WHERE category = 'Stationery';

PRAGMA foreign_keys = ON;

DELETE FROM customers WHERE id = 1;
-- Error: FOREIGN KEY constraint failed (Asha still has orders)

INSERT INTO orders (customer_id, order_date, status)
VALUES (99, '2024-09-01', 'pending');
-- Error: FOREIGN KEY constraint failed (there is no customer 99)

CREATE TABLE members (
  id     INTEGER PRIMARY KEY,
  email  TEXT NOT NULL UNIQUE,
  age    INTEGER CHECK (age >= 18),
  status TEXT DEFAULT 'active'
);

INSERT INTO members (email, age) VALUES ('a@example.com', 20);
SELECT * FROM members;

INSERT INTO members (email, age) VALUES ('a@example.com', 30);
-- UNIQUE constraint failed: members.email

INSERT INTO members (email, age) VALUES (NULL, 30);
-- NOT NULL constraint failed: members.email

INSERT INTO members (email, age) VALUES ('b@example.com', 10);
-- CHECK constraint failed: age >= 18

CREATE INDEX idx_orders_customer_id ON orders (customer_id);

EXPLAIN QUERY PLAN
SELECT * FROM orders WHERE customer_id = 1;

SELECT p.category, p.name, p.price
FROM products AS p
WHERE p.price = (
  SELECT MAX(p2.price) FROM products AS p2 WHERE p2.category = p.category
)
ORDER BY p.category;
